insert into public.projects (id, owner_id, title, description, category, state, help, reach, lat, lng, created_at, updated_at) values
  ('ea000000-0000-4000-8000-000000000001', 'e0000000-0000-4000-8000-000000000008', 'Repaint the faded crosswalks near the school', 'The zebra stripes on both crossings by the elementary school have almost disappeared. The city says ''next year''. I say: one weekend, proper road paint, done. Need a few steady hands and someone who owns a pressure washer.', 'community', 'active', 'local', 'neighborhood', null, null, now() - interval '30 days 19 hours', now() - interval '29 days'),
  ('ea000000-0000-4000-8000-000000000002', 'e0000000-0000-4000-8000-000000000015', 'Community fridge outside the bakery', 'The bakery agreed to host a community fridge on their wall — surplus food in, anyone takes what they need. I need help building the shelter box and a small rota of people to keep it clean.', 'community', 'active', 'local', 'neighborhood', 40.780993, -73.974504, now() - interval '30 days 16 hours', now() - interval '29 days'),
  ('ea000000-0000-4000-8000-000000000003', 'e0000000-0000-4000-8000-000000000022', 'Turn the station underpass into a mural', 'It''s grey, it''s grim, and every kid walks through it daily. I''ve got provisional blessing from the council and two art students — we need painters of any skill level and someone to sweet-talk a paint shop into a discount.', 'community', 'idea', 'both', 'city', null, null, now() - interval '29 days 8 hours', now() - interval '28 days'),
  ('ea000000-0000-4000-8000-000000000004', 'e0000000-0000-4000-8000-000000000029', 'Weekly board game night at the library', 'The library lets us use the back room every Thursday. I have four boxes of games. Come play — and I could use a co-host so it doesn''t die when I''m sick.', 'community', 'active', 'local', 'neighborhood', 40.674211, -73.866488, now() - interval '28 days 8 hours', now() - interval '27 days'),
  ('ea000000-0000-4000-8000-000000000005', 'e0000000-0000-4000-8000-000000000036', 'Fix the creaky bench circle in Miller Park', 'Five benches, all wobbly, one actually dangerous. Wood, screws, one afternoon. The parks office said if we fix them to spec they''ll sign it off.', 'home', 'idea', 'local', 'neighborhood', 40.775589, -73.972970, now() - interval '27 days 3 hours', now() - interval '26 days'),
  ('ea000000-0000-4000-8000-000000000006', 'e0000000-0000-4000-8000-000000000043', 'Neighborhood seed & cutting swap', 'Everyone''s windowsill basil dies alone. Twice a month we swap seeds, cuttings and advice on the church steps. Need a second table and someone who can label things legibly.', 'community', 'active', 'local', 'neighborhood', 40.798274, -73.946103, now() - interval '26 days 3 hours', now() - interval '25 days'),
  ('ea000000-0000-4000-8000-000000000007', 'e0000000-0000-4000-8000-000000000050', 'Teach seniors to video-call their grandkids', 'One hour, one senior, one phone — that''s all it takes. The community center gives us the room. Patient people wanted; tech skills optional, kindness mandatory.', 'learning', 'active', 'local', 'neighborhood', 40.668384, -73.867829, now() - interval '25 days 9 hours', now() - interval '24 days'),
  ('ea000000-0000-4000-8000-000000000008', 'e0000000-0000-4000-8000-000000000057', 'Open-source app for our tool library', 'Our garage tool library is outgrowing the paper notebook. I''m building a tiny lending app (Next.js + Supabase, fittingly) and could use a designer and another dev — from anywhere, honestly.', 'venture', 'active', 'remote', 'global', null, null, now() - interval '24 days 19 hours', now() - interval '23 days'),
  ('ea000000-0000-4000-8000-000000000009', 'e0000000-0000-4000-8000-000000000064', 'Couch-to-5k group, absolute beginners only', 'If you can''t run 400 meters, you''re exactly who this is for. Tuesdays and Saturdays, slower than you think, nobody left behind.', 'fitness', 'active', 'local', 'neighborhood', 40.802320, -73.950783, now() - interval '23 days 4 hours', now() - interval '22 days'),
  ('ea000000-0000-4000-8000-000000000010', 'e0000000-0000-4000-8000-000000000071', 'Rooftop beehive on the co-op building', 'The co-op board said yes (I''m still surprised). Two hives, shared honey, and a pollinator garden on the roof. Need someone who''s kept bees before and a few unafraid helpers.', 'community', 'idea', 'both', 'city', 40.676356, -73.868237, now() - interval '22 days 1 hours', now() - interval '21 days'),
  ('ea000000-0000-4000-8000-000000000011', 'e0000000-0000-4000-8000-000000000078', 'Free bike repair Saturdays', 'I fix bikes in front of my garage, first Saturday every month. Bring your bike, learn to do it yourself. Another pair of greasy hands would double what we can handle.', 'community', 'active', 'local', 'neighborhood', 40.777671, -73.969125, now() - interval '21 days 2 hours', now() - interval '20 days'),
  ('ea000000-0000-4000-8000-000000000012', 'e0000000-0000-4000-8000-000000000085', 'Little free pantry on Elm corner', 'Like a little free library but for cans and pasta. I''ll build the box — I need a spot host with a visible fence and 3-4 people to check on it weekly.', 'community', 'completed', 'local', 'neighborhood', 40.794531, -73.940489, now() - interval '21 days 1 hours', now() - interval '4 days'),
  ('ea000000-0000-4000-8000-000000000013', 'e0000000-0000-4000-8000-000000000092', 'Translate our city''s recycling rules into 6 languages', 'The rules are only in one language and half the street guesses wrong. I''ve got the official text; I need native speakers — anywhere in the world — for Arabic, Vietnamese, Polish, Turkish, Spanish and Ukrainian.', 'community', 'active', 'remote', 'global', null, null, now() - interval '20 days 9 hours', now() - interval '19 days'),
  ('ea000000-0000-4000-8000-000000000014', 'e0000000-0000-4000-8000-000000000099', 'After-school homework club', 'Two retired teachers already in. We take any kid, any subject, Monday to Wednesday at the community hall. Could use two more adults and someone who bakes.', 'learning', 'active', 'local', 'neighborhood', 40.785289, -73.962688, now() - interval '19 days 6 hours', now() - interval '18 days'),
  ('ea000000-0000-4000-8000-000000000015', 'e0000000-0000-4000-8000-000000000006', 'Map every accessible entrance in the city center', 'Wheelchair users shouldn''t need luck to find a way in. We survey shops street by street and publish a free map. Walkers and wheelers welcome; a data person would be gold.', 'community', 'active', 'both', 'city', 40.775713, -73.955606, now() - interval '18 days 9 hours', now() - interval '17 days'),
  ('ea000000-0000-4000-8000-000000000016', 'e0000000-0000-4000-8000-000000000013', 'Restore the old cinema marquee', 'The letters still exist — they''re in the basement! The owner will let us rehang them if we restore them properly. Electricians and stubborn romantics needed.', 'community', 'idea', 'both', 'city', null, null, now() - interval '17 days 9 hours', now() - interval '16 days'),
  ('ea000000-0000-4000-8000-000000000017', 'e0000000-0000-4000-8000-000000000020', 'Podcast about ordinary neighbors doing great things', 'Every episode: one neighbor, one story, thirty minutes. I have mics and enthusiasm; I need an editor (remote is fine) and introverts willing to be interviewed.', 'venture', 'idea', 'remote', 'global', 40.665659, -73.871008, now() - interval '16 days 12 hours', now() - interval '15 days'),
  ('ea000000-0000-4000-8000-000000000018', 'e0000000-0000-4000-8000-000000000027', 'Dog-walking pool for shift workers', 'Nurses and drivers can''t walk dogs at 2pm. We match dogs with neighbors who''d love a walk buddy without owning one. I need five reliable walkers to start.', 'community', 'active', 'local', 'neighborhood', null, null, now() - interval '15 days 20 hours', now() - interval '14 days'),
  ('ea000000-0000-4000-8000-000000000019', 'e0000000-0000-4000-8000-000000000034', 'Repair café — bring your broken things', 'Toasters, trousers, tablets: we fix instead of toss, last Sunday monthly. Have menders for textiles and wood; need an electronics person and a greeter.', 'community', 'active', 'local', 'neighborhood', null, null, now() - interval '14 days 5 hours', now() - interval '13 days'),
  ('ea000000-0000-4000-8000-000000000020', 'e0000000-0000-4000-8000-000000000041', 'Community compost behind the allotments', 'Three bays, proper signage, no rats (promise). The allotment association is in. Need builders for a weekend and households willing to fill it right.', 'community', 'idea', 'local', 'neighborhood', null, null, now() - interval '13 days 14 hours', now() - interval '12 days'),
  ('ea000000-0000-4000-8000-000000000021', 'e0000000-0000-4000-8000-000000000048', 'Oral history of our street, before it''s gone', 'Mrs. Halvorsen is 94 and remembers the street when it had a dairy. I''m recording the elders'' stories before they disappear. Need an interviewer and someone to digitize old photos.', 'learning', 'active', 'both', 'neighborhood', 40.783526, -73.977304, now() - interval '12 days 19 hours', now() - interval '11 days'),
  ('ea000000-0000-4000-8000-000000000022', 'e0000000-0000-4000-8000-000000000055', 'Beginner-friendly community choir', 'No auditions, no sheet-music snobbery. Wednesday nights at St. Anne''s. We have a conductor; we need singers who think they can''t sing and someone to run the socials.', 'community', 'active', 'local', 'city', 40.804491, -73.943680, now() - interval '12 days 4 hours', now() - interval '11 days'),
  ('ea000000-0000-4000-8000-000000000023', 'e0000000-0000-4000-8000-000000000062', 'Solar panels for the sports club roof', 'The quote is doable if we self-organize the paperwork and half the labor. An electrician, a grant-application veteran, and a few Saturday bodies gets it done.', 'venture', 'idea', 'both', 'city', 40.672353, -73.879108, now() - interval '11 days 7 hours', now() - interval '10 days'),
  ('ea000000-0000-4000-8000-000000000024', 'e0000000-0000-4000-8000-000000000069', 'Midnight football under the bridge', 'The five-a-side court is lit and empty every night. Friday midnight kickabout, all levels, zero attitude. Need one more organizer so it survives holidays.', 'fitness', 'active', 'local', 'neighborhood', 40.788828, -73.974242, now() - interval '10 days 14 hours', now() - interval '9 days'),
  ('ea000000-0000-4000-8000-000000000025', 'e0000000-0000-4000-8000-000000000076', 'Sew school-play costumes together', 'The school play needs 30 costumes and has budget for 5. If eight people who can thread a machine give two evenings, every kid gets a costume that fits.', 'home', 'completed', 'local', 'neighborhood', null, null, now() - interval '9 days 15 hours', now() - interval '1 days'),
  ('ea000000-0000-4000-8000-000000000026', 'e0000000-0000-4000-8000-000000000083', 'Neighborhood emergency contact tree', 'When the water main burst nobody knew who to check on. A simple phone tree, block by block, tested twice a year. Need one volunteer per block — that''s it.', 'community', 'active', 'local', 'neighborhood', 40.675233, -73.870230, now() - interval '8 days 10 hours', now() - interval '7 days'),
  ('ea000000-0000-4000-8000-000000000027', 'e0000000-0000-4000-8000-000000000090', 'Open data dashboard for city air quality', 'The sensors exist, the data''s public, nobody can read it. I''m building a plain-language dashboard. Need a frontend dev and a data-viz person — remote welcome.', 'venture', 'active', 'remote', 'global', 40.778848, -73.958545, now() - interval '7 days 11 hours', now() - interval '6 days'),
  ('ea000000-0000-4000-8000-000000000028', 'e0000000-0000-4000-8000-000000000097', 'Saturday morning park cleanup crew', 'One hour, gloves provided, coffee after. The park is ours and it looks like nobody''s. Twelve people would make it spotless monthly.', 'community', 'completed', 'local', 'neighborhood', null, null, now() - interval '6 days 18 hours', now() - interval '4 days'),
  ('ea000000-0000-4000-8000-000000000029', 'e0000000-0000-4000-8000-000000000004', 'Window-box challenge for the greyest street', 'Acacia Street is a concrete canyon. Fifty window boxes would change it completely. I''ve negotiated bulk soil and seedlings; need neighbors to claim a window each.', 'home', 'idea', 'local', 'neighborhood', 40.793531, -73.946481, now() - interval '5 days 7 hours', now() - interval '4 days'),
  ('ea000000-0000-4000-8000-000000000030', 'e0000000-0000-4000-8000-000000000011', 'Learn-to-swim scholarships at the city pool', 'Every year kids in this city drown who never had lessons. The pool offered discounted slots if we organize sign-ups and sponsors. Need organizers and a treasurer type.', 'community', 'idea', 'both', 'city', 40.669586, -73.865860, now() - interval '4 days 3 hours', now() - interval '3 days')
